MERGE INTO uco_entity t
USING (SELECT
    'HL01' case_id,
    'HL01-BOR' entity_id,
    'Aarav Sen Demo' name,
    'individual' entity_type,
    'verified_fixture' identity_status,
    'HL01-KYC' identity_evidence_id
  FROM dual) s
ON (t.case_id = s.case_id AND t.entity_id = s.entity_id)
WHEN NOT MATCHED THEN INSERT (case_id, entity_id, name, entity_type, identity_status, identity_evidence_id)
VALUES (s.case_id, s.entity_id, s.name, s.entity_type, s.identity_status, s.identity_evidence_id);

MERGE INTO uco_entity t
USING (SELECT
    'HL01' case_id,
    'HL01-BUILDER' entity_id,
    'Example Homes Builder Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'HL01-BUILDER-IDENTITY' identity_evidence_id
  FROM dual) s
ON (t.case_id = s.case_id AND t.entity_id = s.entity_id)
WHEN NOT MATCHED THEN INSERT (case_id, entity_id, name, entity_type, identity_status, identity_evidence_id)
VALUES (s.case_id, s.entity_id, s.name, s.entity_type, s.identity_status, s.identity_evidence_id);

MERGE INTO uco_entity t
USING (SELECT
    'HL01' case_id,
    'HL01-TRADER' entity_id,
    'Example Consumer Trading Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'HL01-TRADER-IDENTITY' identity_evidence_id
