MERGE INTO uco_entity t
USING (SELECT
    'CL05' case_id,
    'CL05-BOR' entity_id,
    'Example Ridge Construction Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'CL05-KYC' identity_evidence_id
  FROM dual) s
ON (t.case_id = s.case_id AND t.entity_id = s.entity_id)
WHEN NOT MATCHED THEN INSERT (case_id, entity_id, name, entity_type, identity_status, identity_evidence_id)
VALUES (s.case_id, s.entity_id, s.name, s.entity_type, s.identity_status, s.identity_evidence_id);

MERGE INTO uco_entity t
USING (SELECT
    'CL05' case_id,
    'CL05-INTERMEDIARY' entity_id,
    'Example Material Intermediary Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'CL05-INTERMEDIARY-IDENTITY' identity_evidence_id
  FROM dual) s
ON (t.case_id = s.case_id AND t.entity_id = s.entity_id)
WHEN NOT MATCHED THEN INSERT (case_id, entity_id, name, entity_type, identity_status, identity_evidence_id)
VALUES (s.case_id, s.entity_id, s.name, s.entity_type, s.identity_status, s.identity_evidence_id);

MERGE INTO uco_entity t
USING (SELECT
    'CL05' case_id,
    'CL05-RETURNER' entity_id,
    'Example Settlement Services Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'CL05-RETURNER-IDENTITY' identity_evidence_id
  FROM dual) s
ON (t.case_id = s.case_id AND t.entity_id = s.entity_id)
WHEN NOT MATCHED THEN INSERT (case_id, entity_id, name, entity_type, identity_status, identity_evidence_id)
VALUES (s.case_id, s.entity_id, s.name, s.entity_type, s.identity_status, s.identity_evidence_id);

MERGE INTO uco_drawdown t
USING (SELECT
    'CL05:SYN-DD-CL05' drawdown_id,
    'CL05' case_id,
    8000000 amount_inr,
    TO_TIMESTAMP_TZ('2026-09-21 04:30:00 +00:00', 'YYYY-MM-DD HH24:MI:SS TZH:TZM') posted_at,
    'SYN-DD-CL05' source_ref
  FROM dual) s
ON (t.drawdown_id = s.drawdown_id)
WHEN NOT MATCHED THEN INSERT (drawdown_id, case_id, amount_inr, posted_at, source_ref)
VALUES (s.drawdown_id, s.case_id, s.amount_inr, s.posted_at, s.source_ref);

MERGE INTO uco_payment t
USING (SELECT
    'CL05:CL05-TX01' tx_id,
    'CL05' case_id,
    'CL05-BOR' from_entity,
    'CL05-INTERMEDIARY' to_entity,
    2000000 amount_inr,
    TO_TIMESTAMP('2026-09-21 05:00:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-21T10:30:00+05:30' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    'CL05:SYN-DD-CL05' drawdown_id,
    NULL reversal_of,
    1 corrected_version,
    'CL05-TX01-LEDGER' evidence_id,
    'SYN-FIN-CL05-TX01' source_ref
  FROM dual) s
ON (t.tx_id = s.tx_id)
WHEN MATCHED THEN UPDATE SET t.case_id = s.case_id, t.from_entity = s.from_entity, t.to_entity = s.to_entity, t.amount_inr = s.amount_inr, t.posted_at = s.posted_at, t.original_event_time = s.original_event_time, t.currency = s.currency, t.posting_status = s.posting_status, t.payment_kind = s.payment_kind, t.observed = s.observed, t.drawdown_id = s.drawdown_id, t.reversal_of = s.reversal_of, t.corrected_version = s.corrected_version, t.evidence_id = s.evidence_id, t.source_ref = s.source_ref WHERE s.corrected_version > t.corrected_version
WHEN NOT MATCHED THEN INSERT (tx_id, case_id, from_entity, to_entity, amount_inr, posted_at, original_event_time, currency, posting_status, payment_kind, observed, drawdown_id, reversal_of, corrected_version, evidence_id, source_ref)
VALUES (s.tx_id, s.case_id, s.from_entity, s.to_entity, s.amount_inr, s.posted_at, s.original_event_time, s.currency, s.posting_status, s.payment_kind, s.observed, s.drawdown_id, s.reversal_of, s.corrected_version, s.evidence_id, s.source_ref);

MERGE INTO uco_payment t
USING (SELECT
    'CL05:CL05-TX02' tx_id,
    'CL05' case_id,
    'CL05-INTERMEDIARY' from_entity,
    'CL05-RETURNER' to_entity,
    1900000 amount_inr,
    TO_TIMESTAMP('2026-09-21 06:00:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-21T11:30:00+05:30' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    NULL drawdown_id,
    NULL reversal_of,
    1 corrected_version,
    'CL05-TX02-LEDGER' evidence_id,
    'SYN-FIN-CL05-TX02' source_ref
