    'LEG-split' case_id,
    'LEG-split-BOR' from_entity,
    'LEG-split-REL' to_entity,
    150000 amount_inr,
    TO_TIMESTAMP('2026-09-25 12:50:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-25T12:50:00.000Z' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    'LEG-split:DD-107' drawdown_id,
    NULL reversal_of,
    1 corrected_version,
    'LEG-split-LEG-split-TX1-LEDGER' evidence_id,
    'LEG-split-TX1' source_ref
  FROM dual) s
