    'GOOD-related-REL' to_entity,
    3000000 amount_inr,
    TO_TIMESTAMP('2026-09-25 06:30:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-25T06:30:00.000Z' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    'GOOD-related:DD-142' drawdown_id,
