MERGE INTO uco_entity t
USING (SELECT
    'BOUND-MIDNIGHT' case_id,
    'BOUND-MIDNIGHT-BOR' entity_id,
    'Example Horizon Construction Demo' name,
    'company' entity_type,
    'verified_fixture' identity_status,
    'BOUND-MIDNIGHT-KYC' identity_evidence_id
  FROM dual) s
