MERGE INTO uco_drawdown t
USING (SELECT
    'BOUND-OUTOFORDER:SYN-DD-BOUND-OUTOFORDER' drawdown_id,
    'BOUND-OUTOFORDER' case_id,
    10000000 amount_inr,
    TO_TIMESTAMP_TZ('2026-09-21 04:30:00 +00:00', 'YYYY-MM-DD HH24:MI:SS TZH:TZM') posted_at,
    'SYN-DD-BOUND-OUTOFORDER' source_ref
  FROM dual) s
ON (t.drawdown_id = s.drawdown_id)
WHEN NOT MATCHED THEN INSERT (drawdown_id, case_id, amount_inr, posted_at, source_ref)
VALUES (s.drawdown_id, s.case_id, s.amount_inr, s.posted_at, s.source_ref);

MERGE INTO uco_payment t
USING (SELECT
    'BOUND-OUTOFORDER:BOUND-OUTOFORDER-TX10' tx_id,
    'BOUND-OUTOFORDER' case_id,
    'BOUND-OUTOFORDER-BOR' from_entity,
    'BOUND-OUTOFORDER-PAYEE10' to_entity,
    480000 amount_inr,
    TO_TIMESTAMP('2026-09-21 05:35:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-21T11:05:00+05:30' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    'BOUND-OUTOFORDER:SYN-DD-BOUND-OUTOFORDER' drawdown_id,
    NULL reversal_of,
    1 corrected_version,
    'BOUND-OUTOFORDER-TX10-LEDGER' evidence_id,
    'SYN-FIN-BOUND-OUTOFORDER-TX10' source_ref
  FROM dual) s
