MERGE INTO uco_payment t
USING (SELECT
    'LAB-013:LAB-013-TX01' tx_id,
    'LAB-013' case_id,
    'LAB-013-BOR' from_entity,
    'LAB-013-PAYEE01' to_entity,
    480000 amount_inr,
    TO_TIMESTAMP('2026-09-21 04:50:00', 'YYYY-MM-DD HH24:MI:SS') posted_at,
    '2026-09-21T10:20:00+05:30' original_event_time,
    'INR' currency,
    'posted' posting_status,
    'payment' payment_kind,
    1 observed,
    'LAB-013:SYN-DD-LAB-013' drawdown_id,
    NULL reversal_of,
